  "GetItemEffectParamOffset": {
    returnType: "u8",
    params: "u16 itemId, u8 effectByte, u8 effectBit",
    lineCount: 102,
    bodyC: "const u8 *temp;\n    const u8 *itemEffect;\n    u8 offset;\n    int i;\n    u8 j;\n    u8 effectFlags;\n\n    offset = ITEM_EFFECT_ARG_START;\n\n    temp = gItemEffectTable[itemId - ITEM_POTION];\n\n    if (!temp && itemId != ITEM_ENIGMA_BERRY)\n        return 0;\n\n    if (itemId == ITEM_ENIGMA_BERRY)\n    {\n        temp = gEnigmaBerries[gActiveBattler].itemEffect;\n    }\n\n    itemEffect = temp;\n\n    for (i = 0; i < ITEM_EFFECT_ARG_START; i++)\n    {\n        switch (i)\n        {\n        case 0:\n        case 1:\n        case 2:\n        case 3:\n            if (i == effectByte)\n                return 0;\n            break;\n        case 4:\n            effectFlags = itemEffect[4];\n            if (effectFlags & ITEM4_PP_UP)\n                effectFlags &= ~(ITEM4_PP_UP);\n            j = 0;\n            while (effectFlags)\n            {\n                if (effectFlags & 1)\n                {\n                    switch (j)\n                    {\n                    case 2:  \n                        if (effectFlags & (ITEM4_REVIVE >> 2))\n                            effectFlags &= ~(ITEM4_REVIVE >> 2);\n                         \n                    case 0:  \n                        if (i == effectByte && (effectFlags & effectBit))\n                            return offset;\n                        offset++;\n                        break;\n                    case 1:  \n                        if (i == effectByte && (effectFlags & effectBit))\n                            return offset;\n                        offset++;\n                        break;\n                    case 3:  \n                        if (i == effectByte && (effectFlags & effectBit))\n                            return offset;\n                        offset++;\n                        break;\n                    case 7:  \n                        if (i == effectByte)\n                            return 0;\n                        break;\n                    }\n                }\n                j++;\n                effectFlags >>= 1;\n                if (i == effectByte)\n                    effectBit >>= 1;\n            }\n            break;\n        case 5:\n            effectFlags = itemEffect[5];\n            j = 0;\n            while (effectFlags)\n            {\n                if (effectFlags & 1)\n                {\n                    switch (j)\n                    {\n                    case 0:  \n                    case 1:  \n                    case 2:  \n                    case 3:  \n                    case 4:  \n                    case 5:  \n                    case 6:  \n                        if (i == effectByte && (effectFlags & effectBit))\n                            return offset;\n                        offset++;\n                        break;\n                    case 7:  \n                        if (i == effectByte)\n                            return 0;\n                        break;\n                    }\n                }\n                j++;\n                effectFlags >>= 1;\n                if (i == effectByte)\n                    effectBit >>= 1;\n            }\n            break;\n        }\n    }\n\n    return offset;",
  },
  "GetLevelFromBoxMonExp": {
    returnType: "u8",
    params: "struct BoxPokemon *boxMon",
    callsTo: ["GetBoxMonData"],
    lineCount: 6,
    bodyC: "u16 species = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);\n    u32 exp = GetBoxMonData(boxMon, MON_DATA_EXP, NULL);\n    s32 level = 1;\n\n    while (level <= MAX_LEVEL && gExperienceTables[gSpeciesInfo[species].growthRate][level] <= exp)\n        level++;\n\n    return level - 1;",
  },
