  "GetMonData3": {
    returnType: "u32",
    params: "struct Pokemon *mon, s32 field, u8 *data",
    callsTo: ["GetBoxMonData","GetDeoxysStat"],
    lineCount: 63,
    bodyC: "u32 ret;\n\n    switch (field)\n    {\n    case MON_DATA_STATUS:\n        ret = mon->status;\n        break;\n    case MON_DATA_LEVEL:\n        ret = mon->level;\n        break;\n    case MON_DATA_HP:\n        ret = mon->hp;\n        break;\n    case MON_DATA_MAX_HP:\n        ret = mon->maxHP;\n        break;\n    case MON_DATA_ATK:\n        ret = GetDeoxysStat(mon, STAT_ATK);\n        if (!ret)\n            ret = mon->attack;\n        break;\n    case MON_DATA_DEF:\n        ret = GetDeoxysStat(mon, STAT_DEF);\n        if (!ret)\n            ret = mon->defense;\n        break;\n    case MON_DATA_SPEED:\n        ret = GetDeoxysStat(mon, STAT_SPEED);\n        if (!ret)\n            ret = mon->speed;\n        break;\n    case MON_DATA_SPATK:\n        ret = GetDeoxysStat(mon, STAT_SPATK);\n        if (!ret)\n            ret = mon->spAttack;\n        break;\n    case MON_DATA_SPDEF:\n        ret = GetDeoxysStat(mon, STAT_SPDEF);\n        if (!ret)\n            ret = mon->spDefense;\n        break;\n    case MON_DATA_ATK2:\n        ret = mon->attack;\n        break;\n    case MON_DATA_DEF2:\n        ret = mon->defense;\n        break;\n    case MON_DATA_SPEED2:\n        ret = mon->speed;\n        break;\n    case MON_DATA_SPATK2:\n        ret = mon->spAttack;\n        break;\n    case MON_DATA_SPDEF2:\n        ret = mon->spDefense;\n        break;\n    case MON_DATA_MAIL:\n        ret = mon->mail;\n        break;\n    default:\n        ret = GetBoxMonData(&mon->box, field, data);\n        break;\n    }\n    return ret;",
  },
