  "RandomlyGivePartyPokerus": {
    returnType: "void",
    params: "struct Pokemon *party",
    callsTo: ["CheckPartyHasHadPokerus","GetMonData","Random","SetMonData"],
    lineCount: 26,
    bodyC: "u16 rnd = Random();\n    if (rnd == 0x4000 || rnd == 0x8000 || rnd == 0xC000)\n    {\n        struct Pokemon *mon;\n\n        do\n        {\n            rnd = Random() % PARTY_SIZE;\n            mon = &party[rnd];\n        }\n        while (!GetMonData(mon, MON_DATA_SPECIES, 0) || GetMonData(mon, MON_DATA_IS_EGG, 0));\n\n        if (!(CheckPartyHasHadPokerus(party, gBitTable[rnd])))\n        {\n            u8 rnd2;\n\n            do\n            {\n                rnd2 = Random();\n            }\n            while ((rnd2 & 0x7) == 0);\n\n            if (rnd2 & 0xF0)\n                rnd2 &= 0x7;\n\n            rnd2 |= (rnd2 << 4);\n            rnd2 &= 0xF3;\n            rnd2++;\n\n            SetMonData(&party[rnd], MON_DATA_POKERUS, &rnd2);\n        }\n    }",
  },
