  "SetWildMonHeldItem": {
    returnType: "void",
    params: "void",
    callsTo: ["GetMonAbility","GetMonData","GetWildMonTableIdInAlteringCave","Random","SetMonData"],
    lineCount: 48,
    bodyC: "if (!(gBattleTypeFlags & (BATTLE_TYPE_LEGENDARY | BATTLE_TYPE_TRAINER | BATTLE_TYPE_PYRAMID | BATTLE_TYPE_PIKE)))\n    {\n        u16 rnd = Random() % 100;\n        u16 species = GetMonData(&gEnemyParty[0], MON_DATA_SPECIES, 0);\n        u16 chanceNoItem = 45;\n        u16 chanceNotRare = 95;\n        if (!GetMonData(&gPlayerParty[0], MON_DATA_SANITY_IS_EGG, 0)\n            && GetMonAbility(&gPlayerParty[0]) == ABILITY_COMPOUND_EYES)\n        {\n            chanceNoItem = 20;\n            chanceNotRare = 80;\n        }\n        if (gMapHeader.mapLayoutId == LAYOUT_ALTERING_CAVE)\n        {\n            s32 alteringCaveId = GetWildMonTableIdInAlteringCave(species);\n            if (alteringCaveId != 0)\n            {\n                 \n                if (rnd < chanceNotRare)\n                    return;\n                SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &sAlteringCaveWildMonHeldItems[alteringCaveId].item);\n            }\n            else\n            {\n                 \n                if (rnd < chanceNoItem)\n                    return;\n                if (rnd < chanceNotRare)\n                    SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &gSpeciesInfo[species].itemCommon);\n                else\n                    SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &gSpeciesInfo[species].itemRare);\n            }\n        }\n        else\n        {\n            if (gSpeciesInfo[species].itemCommon == gSpeciesInfo[species].itemRare && gSpeciesInfo[species].itemCommon != ITEM_NONE)\n            {\n                 \n                SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &gSpeciesInfo[species].itemCommon);\n            }\n            else\n            {\n                if (rnd < chanceNoItem)\n                    return;\n                if (rnd < chanceNotRare)\n                    SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &gSpeciesInfo[species].itemCommon);\n                else\n                    SetMonData(&gEnemyParty[0], MON_DATA_HELD_ITEM, &gSpeciesInfo[species].itemRare);\n            }\n        }\n    }",
  },
  "ShouldGetStatBadgeBoost": {
    returnType: "static bool8",
    params: "u16 badgeFlag, u8 battler",
    callsTo: ["FlagGet","GetBattlerSide"],
    lineCount: 10,
    bodyC: "if (gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_EREADER_TRAINER | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))\n        return FALSE;\n    else if (GetBattlerSide(battler) != B_SIDE_PLAYER)\n        return FALSE;\n    else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER && gTrainerBattleOpponent_A == TRAINER_SECRET_BASE)\n        return FALSE;\n    else if (FlagGet(badgeFlag))\n        return TRUE;\n    else\n        return FALSE;",
  },
  "ShouldIgnoreDeoxysForm": {
    returnType: "bool8",
    params: "u8 caseId, u8 battler",
    callsTo: ["GetBattlerSide","GetMultiplayerId"],
    lineCount: 51,
    bodyC: "switch (caseId)\n    {\n    case 0:\n    default:\n        return FALSE;\n    case 1:  \n        if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))\n            return FALSE;\n        if (!gMain.inBattle)\n            return FALSE;\n        if (gLinkPlayers[GetMultiplayerId()].id == battler)\n            return FALSE;\n        break;\n    case 2:\n        break;\n    case 3:  \n        if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))\n            return FALSE;\n        if (!gMain.inBattle)\n            return FALSE;\n        if (battler == 1 || battler == 4 || battler == 5)\n            return TRUE;\n        return FALSE;\n    case 4:\n        break;\n    case 5:  \n        if (gBattleTypeFlags & BATTLE_TYPE_LINK)\n        {\n            if (!gMain.inBattle)\n                return FALSE;\n            if (gBattleTypeFlags & BATTLE_TYPE_MULTI)\n            {\n                if (gLinkPlayers[GetMultiplayerId()].id == battler)\n                    return FALSE;\n            }\n            else\n            {\n                if (GetBattlerSide(battler) == B_SIDE_PLAYER)\n                    return FALSE;\n            }\n        }\n        else\n        {\n            if (!gMain.inBattle)\n                return FALSE;\n            if (GetBattlerSide(battler) == B_SIDE_PLAYER)\n                return FALSE;\n        }\n        break;\n    }\n\n    return TRUE;",
  },
