  "TryIncrementMonLevel": {
    returnType: "bool8",
    params: "struct Pokemon *mon",
    callsTo: ["GetMonData","SetMonData"],
    lineCount: 17,
    bodyC: "u16 species = GetMonData(mon, MON_DATA_SPECIES, 0);\n    u8 nextLevel = GetMonData(mon, MON_DATA_LEVEL, 0) + 1;\n    u32 expPoints = GetMonData(mon, MON_DATA_EXP, 0);\n    if (expPoints > gExperienceTables[gSpeciesInfo[species].growthRate][MAX_LEVEL])\n    {\n        expPoints = gExperienceTables[gSpeciesInfo[species].growthRate][MAX_LEVEL];\n        SetMonData(mon, MON_DATA_EXP, &expPoints);\n    }\n    if (nextLevel > MAX_LEVEL || expPoints < gExperienceTables[gSpeciesInfo[species].growthRate][nextLevel])\n    {\n        return FALSE;\n    }\n    else\n    {\n        SetMonData(mon, MON_DATA_LEVEL, &nextLevel);\n        return TRUE;\n    }",
  },
  "UpdatePartyPokerusTime": {
    returnType: "void",
    params: "u16 days",
    callsTo: ["GetMonData","SetMonData"],
    lineCount: 18,
    bodyC: "int i;\n    for (i = 0; i < PARTY_SIZE; i++)\n    {\n        if (GetMonData(&gPlayerParty[i], MON_DATA_SPECIES, 0))\n        {\n            u8 pokerus = GetMonData(&gPlayerParty[i], MON_DATA_POKERUS, 0);\n            if (pokerus & 0xF)\n            {\n                if ((pokerus & 0xF) < days || days > 4)\n                    pokerus &= 0xF0;\n                else\n                    pokerus -= days;\n\n                if (pokerus == 0)\n                    pokerus = 0x10;\n\n                SetMonData(&gPlayerParty[i], MON_DATA_POKERUS, &pokerus);\n            }\n        }\n    }",
  },
  "UseStatIncreaseItem": {
    returnType: "u8 *",
    params: "u16 itemId",
    callsTo: ["BattleStringExpandPlaceholdersToDisplayedString","BufferStatRoseMessage"],
    lineCount: 37,
    bodyC: "int i;\n    const u8 *itemEffect;\n\n    if (itemId == ITEM_ENIGMA_BERRY)\n    {\n        if (gMain.inBattle)\n            itemEffect = gEnigmaBerries[gBattlerInMenuId].itemEffect;\n        else\n            itemEffect = gSaveBlock1Ptr->enigmaBerry.itemEffect;\n    }\n    else\n    {\n        itemEffect = gItemEffectTable[itemId - ITEM_POTION];\n    }\n\n    gPotentialItemEffectBattler = gBattlerInMenuId;\n\n    for (i = 0; i < 3; i++)\n    {\n        if (itemEffect[i] & (ITEM0_X_ATTACK | ITEM1_X_SPEED | ITEM2_X_SPATK))\n            BufferStatRoseMessage(i * 2);\n\n        if (itemEffect[i] & (ITEM0_DIRE_HIT | ITEM1_X_DEFEND | ITEM2_X_ACCURACY))\n        {\n            if (i != 0)  \n            {\n                BufferStatRoseMessage(i * 2 + 1);\n            }\n            else\n            {\n                gBattlerAttacker = gBattlerInMenuId;\n                BattleStringExpandPlaceholdersToDisplayedString(gText_PkmnGettingPumped);\n            }\n        }\n    }\n\n    if (itemEffect[3] & ITEM3_GUARD_SPEC)\n    {\n        gBattlerAttacker = gBattlerInMenuId;\n        BattleStringExpandPlaceholdersToDisplayedString(gText_PkmnShroudedInMist);\n    }\n\n    return gDisplayedStringBattle;",
  },
